import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import { cn } from '../../utils/cn';
import { headingVariants, textVariants } from './text.variants';

export type TextVariant = 'body' | 'label' | 'supporting' | 'caption' | 'code' | 'display';
export type TextTone = 'default' | 'muted' | 'primary' | 'success' | 'warning' | 'destructive' | 'inherit';

/** Tone each variant uses when `tone` is not set. */
const DEFAULT_TONE: Record<TextVariant, TextTone> = {
  body: 'default',
  label: 'default',
  supporting: 'muted',
  caption: 'muted',
  code: 'default',
  display: 'default',
};

const DEFAULT_TAG: Record<TextVariant, 'p' | 'span' | 'code'> = {
  body: 'p',
  label: 'span',
  supporting: 'p',
  caption: 'span',
  code: 'code',
  display: 'p',
};

export interface TextProps extends Omit<useRender.ComponentProps<'p'>, 'className'> {
  className?: string;
  /** Type role. Default `body`. */
  variant?: TextVariant;
  /** Colour role; brand / status tones use the contrast-safe `*-text` aliases. Defaults per variant. */
  tone?: TextTone;
  /** Tag to render; defaults per variant (p, span or code). `render` wins when both are set. */
  as?: 'p' | 'span' | 'div' | 'code' | 'small' | 'strong' | 'em' | 'label' | 'dt' | 'dd' | 'li' | 'figcaption';
  /** Single line with an ellipsis. */
  truncate?: boolean;
  /** Clamp to N lines (1–6) with an ellipsis. */
  lineClamp?: 1 | 2 | 3 | 4 | 5 | 6;
}

/** Body copy and small type roles: body, label, supporting, caption, code and display. */
export function Text({ variant = 'body', tone, as, truncate, lineClamp, className, render, ref, ...props }: TextProps) {
  return useRender({
    defaultTagName: as ?? DEFAULT_TAG[variant],
    render,
    ref,
    props: mergeProps<'p'>(props, {
      className: cn(textVariants({ variant, tone: tone ?? DEFAULT_TONE[variant], truncate, lineClamp }), className),
    }),
  });
}

export type HeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;
export type HeadingSize = 'display' | 'xl' | 'lg' | 'md' | 'sm' | 'xs' | '2xs';

const LEVEL_SIZE: Record<HeadingLevel, HeadingSize> = { 1: 'xl', 2: 'lg', 3: 'md', 4: 'sm', 5: 'xs', 6: '2xs' };

export interface HeadingProps extends Omit<useRender.ComponentProps<'h2'>, 'className'> {
  className?: string;
  /** Semantic level (h1–h6) that fits the page outline. Default 2. */
  level?: HeadingLevel;
  /** Visual size, independent of the level. Defaults to the level's size. */
  size?: HeadingSize;
  tone?: 'default' | 'muted' | 'primary' | 'inherit';
  truncate?: boolean;
  lineClamp?: 1 | 2 | 3;
}

/** Section and page titles: the semantic level and the visual size are chosen separately. */
export function Heading({
  level = 2,
  size,
  tone,
  truncate,
  lineClamp,
  className,
  render,
  ref,
  ...props
}: HeadingProps) {
  return useRender({
    defaultTagName: `h${level}`,
    render,
    ref,
    props: mergeProps<'h2'>(props, {
      className: cn(headingVariants({ size: size ?? LEVEL_SIZE[level], tone, truncate, lineClamp }), className),
    }),
  });
}

export {
  Text,
  Heading,
  type TextProps,
  type TextVariant,
  type TextTone,
  type HeadingProps,
  type HeadingLevel,
  type HeadingSize,
} from './Text';
export { textVariants, headingVariants, type TextVariantProps, type HeadingVariantProps } from './text.variants';
export { doc as textDoc } from './Text.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const textVariants = tv({
  base: 'min-w-0',
  variants: {
    variant: {
      body: 'text-body',
      label: 'text-label',
      supporting: 'text-supporting',
      caption: 'text-caption',
      code: 'rounded-sm bg-secondary px-1 py-0.5 font-mono text-[0.92em]',
      display: 'text-display',
    },
    tone: {
      default: 'text-foreground',
      muted: 'text-muted-foreground',
      primary: 'text-primary-text',
      success: 'text-success-text',
      warning: 'text-warning-text',
      destructive: 'text-destructive-text',
      inherit: 'text-inherit',
    },
    truncate: { true: 'truncate' },
    lineClamp: {
      1: 'line-clamp-1',
      2: 'line-clamp-2',
      3: 'line-clamp-3',
      4: 'line-clamp-4',
      5: 'line-clamp-5',
      6: 'line-clamp-6',
    },
  },
  defaultVariants: { variant: 'body' },
});

export const headingVariants = tv({
  base: 'min-w-0 text-balance',
  variants: {
    size: {
      display: 'text-display',
      xl: 'text-heading-xl',
      lg: 'text-heading-lg',
      md: 'text-heading-md',
      sm: 'text-heading-sm',
      xs: 'text-heading-xs',
      '2xs': 'text-heading-2xs',
    },
    tone: {
      default: 'text-foreground',
      muted: 'text-muted-foreground',
      primary: 'text-primary-text',
      inherit: 'text-inherit',
    },
    truncate: { true: 'truncate' },
    lineClamp: {
      1: 'line-clamp-1',
      2: 'line-clamp-2',
      3: 'line-clamp-3',
    },
  },
  defaultVariants: { tone: 'default' },
});

export type TextVariantProps = VariantProps<typeof textVariants>;
export type HeadingVariantProps = VariantProps<typeof headingVariants>;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
